function kMasFrecuentes(nums, k) {
  const freq = new Map();
  for (const x of nums) freq.set(x, (freq.get(x) ?? 0) + 1);
  const cubetas = Array.from({ length: nums.length + 1 }, () => []);
  for (const [x, f] of freq) cubetas[f].push(x);
  const res = [];
  for (let f = cubetas.length - 1; f > 0 && res.length < k; f--) {
    for (const x of cubetas[f]) {
      res.push(x);
      if (res.length === k) break;
    }
  }
  return res;
}

solution.python:
from collections import Counter

def kMasFrecuentes(nums, k):
    freq = Counter(nums)
    cubetas = [[] for _ in range(len(nums) + 1)]
    for x, f in freq.items():
        cubetas[f].append(x)
    res = []
    for f in range(len(cubetas) - 1, 0, -1):
        for x in cubetas[f]:
            res.append(x)
            if len(res) == k:
                return res
    return res
